# Summary

The RCE vulnerability was discovered on /api/function/execute in latest version of SIM. 
The functionality has user-controllable parameter without any blacklist/whitelist filtering 
or special character escaping security measures, allowing attackers to execute arbitrary javascript code.

# Details

- apps\sim\app\api\function\execute\route.ts
```
export async function POST(req: NextRequest) {
  const requestId = crypto.randomUUID().slice(0, 8)
  const startTime = Date.now()

  try {
    const body = await req.json()
    const { code, params = {}, timeout = 5000 } = body

    logger.info(`[${requestId}] Function execution request`, {
      hasCode: !!code,
      paramsCount: Object.keys(params).length,
      timeout
    })


    const context = createContext({
      params: params,
      fetch: globalThis.fetch || require('node-fetch').default,
      console: {
        log: (...args: any[]) => {
        }
      }
    })

    const script = new Script(`
      (async () => {
        try {
          ${code}
        } catch (error) {
          console.error(error);
          throw error;
        }
      })()
    `, { filename: 'user-function.js' })

    // sink
    const result = await script.runInContext(context, {
      timeout,
      displayErrors: true
    })

    return NextResponse.json({
      success: true,
      output: {
        result,
        executionTime: Date.now() - startTime
      }
    })
  } catch (error) {
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}
